    MAX_ATR_HEIGHT = 4
    TAKE_PROFIT_ATR = 3
    PYRAMID_ATR = 2
    MAX_PYRAMID_ADDS = 2
    TIME_STOP_BARS = 32
    RISK_PERCENT = 0.01
    ATR_MULTIPLIER = 2

