    low_box = ind.lowest(hist.low, BOX_PERIOD)[:-1][-1]
    box_height = high_box - low_box

    # Determine position size
    position_size = RISK_PERCENT * hist.close[-1] / (ATR_MULTIPLIER * entry_atr)
