    if 'entry_atr' not in state:
        state['entry_atr'] = 0
    if 'entry_time' not in state:
        state['entry_time'] = 0

    # Check for new entry conditions
    if pos == 0:
        if hist.close[-1] > high_box and box_height <= MAX_ATR_HEIGHT * entry_atr:
            # Long entry
            state['entry_price'] = hist.close[-1]
            state['last_add_price'] = hist.close[-1]
            state['pyramid_adds'] = 0
            state['entry_atr'] = entry_atr
            state['entry_time'] = len(hist) - 1
            return {"target": position_size, "stop": low_box, "take": state['entry_price'] + TAKE_PROFIT_ATR * entry_atr}
        elif hist.close[-1] < low_box and box_height <= MAX_ATR_HEIGHT * entry_atr:
            # Short entry
            state['entry_price'] = hist.close[-1]
            state['last_add_price'] = hist.close[-1]
            state['pyramid_adds'] = 0
            state['entry_atr'] = entry_atr
            state['entry_time'] = len(hist) - 1
            return {"target": -position_size, "stop": high_box, "take": state['entry_price'] - TAKE_PROFIT_ATR * entry_atr}

    # Check for pyramid conditions
    if pos > 0 and state['pyramid_adds'] < MAX_PYRAMID_ADDS:
        if hist.close[-1] >= state['last_add_price'] + PYRAMID_ATR * entry_atr:
            state['last_add_price'] = hist.close[-1]
            state['pyramid_adds'] += 1
            return {"target": pos + position_size, "stop": low_box, "take": state['entry_price'] + TAKE_PROFIT_ATR * entry_atr}
    elif pos < 0 and state['pyramid_adds'] < MAX_PYRAMID_ADDS:
        if hist.close[-1] <= state['last_add_price'] - PYRAMID_ATR * entry_atr:
            state['last_add_price'] = hist.close[-1]
            state['pyramid_adds'] += 1
            return {"target": pos - position_size, "stop": high_box, "take": state['entry_price'] - TAKE_PROFIT_ATR * entry_atr}

    # Check for time stop
    if len(hist) - 1 - state['entry_time'] >= TIME_STOP_BARS:
        return {"target": 0, "stop": None, "take": None}

    # Check for opposite box close to flip position
    if pos > 0 and hist.close[-1] < low_box:
        return {"target": -position_size, "stop": high_box, "take": state['entry_price'] - TAKE_PROFIT_ATR * entry_atr}
    elif pos < 0 and hist.close[-1] > high_box:
