import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    RISK_PERCENTAGE = 0.01  # 1% risk per trade
    ATR_MULTIPLIER = 2      # ATR multiplier for stop
    TAKE_PROFIT_MULTIPLIER = 1  # ATR multiplier for take profit
    BAR_LIMIT = 32          # Maximum number of bars for a trade
    DONCHIAN_PERIOD = 48    # Period for Donchian channel

    # Calculate indicators
    atr = ind.atr(hist, 14)
    highest_48 = ind.highest(hist.high, DONCHIAN_PERIOD)
    lowest_48 = ind.lowest(hist.low, DONCHIAN_PERIOD)

    # Current bar index
    t = len(hist) - 1

    # Determine entry ATR
    if 'entry_atr' not in state:
        state['entry_atr'] = atr[t]

    # Determine position size
    position_size = RISK_PERCENTAGE * hist.close[t] / (ATR_MULTIPLIER * state['entry_atr'])
    position_size = round(position_size / 0.05) * 0.05  # Round to 0.05 grid

    # Determine take profit and stop loss levels
    take_profit = hist.close[t] + TAKE_PROFIT_MULTIPLIER * state['entry_atr']
    stop_loss = hist.close[t] - ATR_MULTIPLIER * state['entry_atr']

    # Check for opposite signal to close position
    if pos > 0 and hist.close[t] <= lowest_48[t]:
        return {"target": 0, "stop": None, "take": None}
    if pos < 0 and hist.close[t] >= highest_48[t]:
        return {"target": 0, "stop": None, "take": None}

    # Check for breakout signal to enter position
    if pos == 0:
        if hist.close[t] >= highest_48[t]:
            return {"target": position_size, "stop": stop_loss, "take": take_profit}
        if hist.close[t] <= lowest_48[t]:
            return {"target": -position_size, "stop": stop_loss, "take": take_profit}

    # Ratchet stop loss
    if pos > 0:
        stop_loss = max(stop_loss, hist.high[t] - ATR_MULTIPLIER * state['entry_atr'])
    if pos < 0:
        stop_loss = min(stop_loss, hist.low[t] + ATR_MULTIPLIER * state['entry_atr'])

    # Check for bar limit to close position
    if 'entry_bar' not in state:
        state['entry_bar'] = t
    if t - state['entry_bar'] >= BAR_LIMIT:
        return {"target": 0, "stop": None, "take": None}

    # Return current position with updated stop and take
    return {"target": pos, "stop": stop_loss, "take": take_profit}

