def strategy(hist, state, pos, ind) -> dict:
    # Constants
    LOOKBACK = 96
    RISK_PERCENT = 0.01
    ATR_PERIOD = 14
    TIME_STOP_BARS = 32
    ATR_MULTIPLIER = 1.0
    POSITION_CAP = 1.0
    POSITION_FLOOR = 0.05

    # Calculate the 96-bar high and low
    prior_96_bar_high = ind.highest(hist.high, LOOKBACK + 1)[:-1][-1]
    prior_96_bar_low = ind.lowest(hist.low, LOOKBACK + 1)[:-1][-1]

    # Calculate ATR
    atr = ind.atr(hist, ATR_PERIOD)
    entry_atr = atr[-1] if pos == 0 else state['entry_atr']

    # Determine target position size
    if pos == 0:
        if hist.close[-1] > prior_96_bar_high:
            # Calculate position size
            position_size = (RISK_PERCENT * hist.close[-1]) / (ATR_MULTIPLIER * entry_atr)
            position_size = min(max(position_size, POSITION_FLOOR), POSITION_CAP)
            position_size = round(position_size / 0.05) * 0.05  # Round to 0.05 grid
            state['entry_atr'] = entry_atr
            state['entry_bar'] = len(hist) - 1
            state['target'] = position_size
        elif hist.close[-1] < prior_96_bar_low:
            return {"target": 0, "stop": None, "take": None}
        else:
            return {"target": pos, "stop": None, "take": None}
    else:
        # Check for time stop
        if len(hist) - 1 - state['entry_bar'] >= TIME_STOP_BARS:
            return {"target": 0, "stop": None, "take": None}

        # Set stop and take levels
        stop_level = prior_96_bar_low
        take_level = None  # No take-profit in this strategy

        return {"target": state['target'], "stop": stop_level, "take": take_level}

    return {"target": pos, "stop": None, "take": None}

