            if pos == 0:
                # Calculate position size
                position_size = POSITION_SIZE * RISK_PERCENT * hist.close[-1] / (ATR_MULTIPLIER * entry_atr)
                position_size = round(position_size / 0.05) * 0.05
                position_size = min(position_size, 1)  # Cap position size to 1
                return {
                    "target": position_size,
                    "stop": hist.close[-1] - STOP_ATR * entry_atr,
                    "take": None
                }
            elif pos < 0:
                return {"target": 0, "stop": None, "take": None}

        # Check for breakout below the box
        if hist.close[-1] < box_bottom:
            if pos == 0:
                # Calculate position size
                position_size = POSITION_SIZE * RISK_PERCENT * hist.close[-1] / (ATR_MULTIPLIER * entry_atr)
                position_size = round(position_size / 0.05) * 0.05
                position_size = max(position_size, -1)  # Floor position size to -1
                return {
                    "target": position_size,
                    "stop": hist.close[-1] + STOP_ATR * entry_atr,
                    "take": None
                }
            elif pos > 0:
                return {"target": 0, "stop": None, "take": None}

    # Time stop
    if pos != 0:
        if 'entry_bar' not in state:
            state['entry_bar'] = len(hist) - 1
        if len(hist) - state['entry_bar'] >= TIME_STOP_BARS:
            return {"target": 0, "stop": None, "take": None}

    # Maintain current position and stop/take levels
    if pos != 0:
        return {
            "target": pos,
            "stop": state.get('stop'),
