def strategy(hist, state, pos, ind) -> dict:
    # Constants
    N = 48
    ARMED_BARS = 8
    RISK_PERCENT = 0.5  # 50% equity
    ATR_PERIOD = 14
    K_ATR = 1

    # Calculate necessary indicators
    atr_values = ind.atr(hist, ATR_PERIOD)
    highest_48 = ind.highest(hist.high, N)
    lowest_48 = ind.lowest(hist.low, N)

    # Current bar index
    t = len(hist) - 1

    # Entry ATR
    if 'entry_atr' not in state:
        state['entry_atr'] = 0.0

    # Determine position sizing
    position_size = 0.0
    if pos == 0:
        position_size = RISK_PERCENT * hist.close[t] / (K_ATR * atr_values[t])
        position_size = round(position_size / 0.05) * 0.05  # Round to 0.05 grid

    # State management
    if 'armed_level' not in state:
        state['armed_level'] = 0.0
    if 'armed_since' not in state:
        state['armed_since'] = 0
    if 'entry_price' not in state:
        state['entry_price'] = 0.0

    # Check for new Donchian high to reset the clock
    if hist.high[t] > highest_48[t - 1]:
        state['armed_level'] = highest_48[t]
        state['armed_since'] = t

    # Arm the setup if price closes above the 48-bar high
    if hist.close[t] > highest_48[t - 1]:
        state['armed_level'] = highest_48[t]
        state['armed_since'] = t

    # Check if we are armed and the low touches the armed level
    if pos == 0 and state['armed_since'] > 0 and t - state['armed_since'] < ARMED_BARS:
        if hist.low[t] <= state['armed_level']:
            state['entry_price'] = hist.close[t]
            state['entry_atr'] = atr_values[t]
            return {"target": position_size, "stop": None, "take": None}

    # Check for bearish signal to get flat
    if pos > 0:
        if hist.close[t] < lowest_48[t - 1]:
            for i in range(1, ARMED_BARS + 1):
                if hist.high[t - i] >= lowest_48[t - 1]:
                    return {"target": 0.0, "stop": None, "take": None}

    # Bail at the open once 32 bars tick from entry
    if pos > 0:
        if t - state['armed_since'] >= 32:
            return {"target": 0.0, "stop": None, "take": None}

    # Set stop and take-profit levels
    stop_level = state['entry_price'] - 2 * state['entry_atr']
    take_level = state['entry_price'] + 2 * state['entry_atr']

    return {"target": pos, "stop": stop_level, "take": take_level}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    DONCHIAN_PERIOD = 96
    RISK_PERCENT = 0.01
    ATR_MULT_STOP = 2
    ATR_MULT_TAKE = 3
    ATR_MULT_TRAIL = 1.5
    ATR_MULT_PYRAMID = 1
    MAX_ADDS = 2
    TIME_STOP_BARS = 16

    # Calculate indicators
    atr = ind.atr(hist, ATR_PERIOD)
    highest = ind.highest(hist.high, DONCHIAN_PERIOD)
    lowest = ind.lowest(hist.low, DONCHIAN_PERIOD)

    # Current bar data
    current_close = hist.close[-1]
    current_high = hist.high[-1]
    current_low = hist.low[-1]
    current_time = hist.time[-1]

    # Determine breakout signals
    long_signal = current_close > highest[-2]
    short_signal = current_close < lowest[-2]

    # Initialize state variables if not already set
    if 'entry_price' not in state:
        state['entry_price'] = 0.0
    if 'entry_atr' not in state:
        state['entry_atr'] = 0.0
    if 'stop_price' not in state:
        state['stop_price'] = 0.0
    if 'take_price' not in state:
        state['take_price'] = 0.0
    if 'trail_stop' not in state:
        state['trail_stop'] = 0.0
    if 'adds' not in state:
        state['adds'] = 0
    if 'last_add_price' not in state:
        state['last_add_price'] = 0.0
    if 'entry_time' not in state:
        state['entry_time'] = 0

    # Check for time stop
    if pos != 0 and len(hist) - state['entry_time'] >= TIME_STOP_BARS:
        return {"target": 0.0, "stop": None, "take": None}

    # Check for opposite signal to close position
    if pos > 0 and short_signal:
        return {"target": 0.0, "stop": None, "take": None}
    if pos < 0 and long_signal:
        return {"target": 0.0, "stop": None, "take": None}

    # Determine position size
    if pos == 0:
        if long_signal or short_signal:
            state['entry_price'] = current_close
            state['entry_atr'] = atr[-1]
            state['adds'] = 0
            state['last_add_price'] = current_close
            state['entry_time'] = len(hist)

            # Calculate initial position size
            position_size = RISK_PERCENT * current_close / (ATR_MULT_STOP * state['entry_atr'])
            position_size = round(position_size / 0.05) * 0.05
            position_size = max(0.05, min(1.0, position_size))  # Cap between 0.05 and 1.0

            # Set initial stop and take
            state['stop_price'] = state['entry_price'] - ATR_MULT_STOP * state['entry_atr']
            state['take_price'] = state['entry_price'] + ATR_MULT_TAKE * state['entry_atr']
            state['trail_stop'] = state['entry_price'] - ATR_MULT_TRAIL * state['entry_atr']

            return {"target": position_size if long_signal else -position_size, "stop": state['stop_price'], "take": state['take_price']}

    # Manage existing position
    if pos != 0:
        # Update trailing stop
        if pos > 0:
            state['trail_stop'] = max(state['trail_stop'], current_high - ATR_MULT_TRAIL * state['entry_atr'])
        else:
            state['trail_stop'] = min(state['trail_stop'], current_low + ATR_MULT_TRAIL * state['entry_atr'])

        # Check for stop or take
        if pos > 0 and (current_low <= state['stop_price'] or current_low <= state['trail_stop']):
            return {"target": 0.0, "stop": None, "take": None}
        if pos < 0 and (current_high >= state['stop_price'] or current_high >= state['trail_stop']):
            return {"target": 0.0, "stop": None, "take": None}
        if pos > 0 and current_high >= state['take_price']:
            return {"target": 0.0, "stop": None, "take": None}
        if pos < 0 and current_low <= state['take_price']:
            return {"target": 0.0, "stop": None, "take": None}

        # Pyramid up
        if state['adds'] < MAX_ADDS:
            if pos > 0 and current_close >= state['last_add_price'] + ATR_MULT_PYRAMID * state['entry_atr']:
                state['last_add_price'] = current_close
                state['adds'] += 1
                return {"target": pos + 0.25, "stop": state['stop_price'], "take": state['take_price']}
            if pos < 0 and current_close <= state['last_add_price'] - ATR_MULT_PYRAMID * state['entry_atr']:
                state['last_add_price'] = current_close
                state['adds'] += 1
                return {"target": pos - 0.25, "stop": state['stop_price'], "take": state['take_price']}

        # Ratchet take-profit
        if pos > 0 and current_close >= state['take_price'] - 2 * state['entry_atr']:
            state['take_price'] = current_close + ATR_MULT_TAKE * state['entry_atr']
        if pos < 0 and current_close <= state['take_price'] + 2 * state['entry_atr']:
            state['take_price'] = current_close - ATR_MULT_TAKE * state['entry_atr']

    # Return current position and orders
    return {"target": pos, "stop": state['stop_price'], "take": state['take_price']}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    DONCHIAN_PERIOD = 48
    SETUP_DURATION = 8
    RISK_PERCENT = 0.5  # 50% equity
    ATR_MULT_STOP = 3
    ATR_MULT_SCALE = 1.5
    ATR_MULT_TRAIL = 1.5
    HTF_PERIOD = 240  # 4-hour candles
    EMA_PERIOD = 50

    # Calculate indicators
    atr = ind.atr(hist, ATR_PERIOD)
    htf_close = hist.htf(HTF_PERIOD).close
    htf_ema = ind.ema(htf_close, EMA_PERIOD)
    donchian_high = ind.highest(hist.high, DONCHIAN_PERIOD)
    donchian_low = ind.lowest(hist.low, DONCHIAN_PERIOD)

    # Current bar index
    t = len(hist) - 1

    # Initialize state variables if not already set
    if 'entry_price' not in state:
        state['entry_price'] = 0.0
    if 'entry_atr' not in state:
        state['entry_atr'] = 0.0
    if 'setup_level' not in state:
        state['setup_level'] = 0.0
    if 'setup_start' not in state:
        state['setup_start'] = 0
    if 'scale_out_price' not in state:
        state['scale_out_price'] = 0.0
    if 'trail_price' not in state:
        state['trail_price'] = 0.0

    # Check for breakout and setup
    if pos == 0:
        if hist.close[t] > donchian_high[t - 1]:
            state['setup_level'] = donchian_high[t - 1]
            state['setup_start'] = t
        elif state['setup_level'] > 0 and hist.close[t] <= state['setup_level'] and t - state['setup_start'] < SETUP_DURATION:
            if htf_close[t] > htf_ema[t]:
                # Enter long
                state['entry_price'] = hist.close[t]
                state['entry_atr'] = atr[t]
                state['scale_out_price'] = state['entry_price'] + ATR_MULT_SCALE * state['entry_atr']
                state['trail_price'] = state['entry_price'] + ATR_MULT_TRAIL * state['entry_atr']
                target = RISK_PERCENT * hist.close[t] / (ATR_MULT_STOP * state['entry_atr'])
                target = round(target / 0.05) * 0.05
                return {"target": target, "stop": state['entry_price'] - ATR_MULT_STOP * state['entry_atr'], "take": None}

    # Manage open position
    if pos > 0:
        # Update trailing stop
        state['trail_price'] = max(state['trail_price'], hist.high[t] - ATR_MULT_TRAIL * state['entry_atr'])

        # Check for scale out
        if hist.high[t] >= state['scale_out_price']:
            return {"target": pos / 2, "stop": state['entry_price'] - ATR_MULT_STOP * state['entry_atr'], "take": None}

        # Check for stop loss
        if hist.low[t] <= state['entry_price'] - ATR_MULT_STOP * state['entry_atr']:
            return {"target": 0, "stop": None, "take": None}

        # Check for trailing stop
        if hist.low[t] <= state['trail_price']:
            return {"target": 0, "stop": None, "take": None}

        # Check for take profit
        if hist.high[t] >= state['entry_price'] + ATR_MULT_SCALE * state['entry_atr']:
            return {"target": pos / 2, "stop": state['entry_price'] - ATR_MULT_STOP * state['entry_atr'], "take": None}

        # Return current position with updated stop and take
        return {"target": pos, "stop": state['entry_price'] - ATR_MULT_STOP * state['entry_atr'], "take": state['trail_price']}

    # No position, no setup
    return {"target": 0, "stop": None, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    MACD_FAST = 12
    MACD_SLOW = 26
    MACD_SIGNAL = 9
    EMA_PERIOD = 50
    ATR_PERIOD = 14
    RISK_PERCENT = 0.005
    ATR_MULT_TP = 3
    TIME_STOP_BARS = 128
    COOLDOWN_BARS = 16

    # Calculate indicators
    macd_line, signal_line, _ = ind.macd(hist.close, MACD_FAST, MACD_SLOW, MACD_SIGNAL)
    atr = ind.atr(hist, ATR_PERIOD)
    htf_4h = hist.htf(240)
    htf_ema_50 = ind.ema(htf_4h.close, EMA_PERIOD)

    # Current bar index
    t = len(hist) - 1

    # Check for cooldown
    if 'last_trade_bar' in state and t - state['last_trade_bar'] < COOLDOWN_BARS:
        return {"target": pos, "stop": None, "take": None}

    # Determine entry conditions
    macd_cross_up = macd_line[t] > signal_line[t] and macd_line[t-1] <= signal_line[t-1]
    macd_cross_down = macd_line[t] < signal_line[t] and macd_line[t-1] >= signal_line[t-1]
    htf_4h_above_ema = htf_4h.close[t // 16] > htf_ema_50[t // 16]
    htf_4h_below_ema = htf_4h.close[t // 16] < htf_ema_50[t // 16]

    # Entry logic
    if pos == 0:
        if macd_cross_up and htf_4h_above_ema:
            entry_price = hist.close[t]
            entry_atr = atr[t]
            position_size = RISK_PERCENT * entry_price / entry_atr
            position_size = round(position_size / 0.05) * 0.05
            take_price = entry_price + ATR_MULT_TP * entry_atr
            stop_price = None
            state['last_trade_bar'] = t
            return {"target": position_size, "stop": stop_price, "take": take_price}
        elif macd_cross_down and htf_4h_below_ema:
            entry_price = hist.close[t]
            entry_atr = atr[t]
            position_size = -RISK_PERCENT * entry_price / entry_atr
            position_size = round(position_size / 0.05) * 0.05
