    # Exit logic
    if pos > 0:
        if macd_cross_down:
            return {"target": 0, "stop": None, "take": None}
        if t - state['last_trade_bar'] >= TIME_STOP_BARS:
            return {"target": 0, "stop": None, "take": None}
    elif pos < 0:
        if macd_cross_up:
            return {"target": 0, "stop": None, "take": None}
        if t - state['last_trade_bar'] >= TIME_STOP_BARS:
            return {"target": 0, "stop": None, "take": None}

    # Maintain stop and take levels
    if pos > 0:
        stop_price = hist.close[t] - 2 * atr[t]
