        state['anchor'] = hist.close[-1]
        state['entry_atr'] = entry_atr
        return {"target": -1.0, "stop": state['anchor'] + ATR_MULT_STOP * state['entry_atr'], "take": state['anchor'] - ATR_MULT_TAKE * state['entry_atr']}

