def strategy(hist, state, pos, ind) -> dict:
    # Constants
    RISK_PERCENTAGE = 0.5  # 50% equity
    ATR_MULTIPLIER = 1.0   # 1 ATR
    MAX_POSITION = 1.0     # 100% equity
    COOLDOWN_BARS = 16     # 16 bars cooldown after trade end

    # Calculate MACD
    macd_line, signal_line, _ = ind.macd(hist.close, 12, 26, 9)

    # Calculate ATR
    atr = ind.atr(hist, 14)

    # Determine if we are in a cooldown period
    in_cooldown = state.get('in_cooldown', False)
    if in_cooldown:
        if state.get('cooldown_counter', 0) >= COOLDOWN_BARS:
            del state['in_cooldown']
            del state['cooldown_counter']
        else:
            state['cooldown_counter'] = state.get('cooldown_counter', 0) + 1
        return {"target": pos, "stop": None, "take": None}

    # Determine if we should enter a trade
    if pos == 0:
        if macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]:
            # Go long
            entry_price = hist.close[-1]
            entry_atr = atr[-1]
            position_size = RISK_PERCENTAGE * entry_price / (ATR_MULTIPLIER * entry_atr)
            position_size = min(position_size, MAX_POSITION)
            state['last_add_price'] = entry_price
            state['position_size'] = position_size
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            return {"target": position_size, "stop": entry_price - 2 * entry_atr, "take": None}
        elif macd_line[-1] < signal_line[-1] and macd_line[-2] >= signal_line[-2]:
            # Go short
            entry_price = hist.close[-1]
            entry_atr = atr[-1]
            position_size = -RISK_PERCENTAGE * entry_price / (ATR_MULTIPLIER * entry_atr)
            position_size = max(position_size, -MAX_POSITION)
            state['last_add_price'] = entry_price
            state['position_size'] = position_size
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            return {"target": position_size, "stop": entry_price + 2 * entry_atr, "take": None}

    # Determine if we should pyramid
    if pos > 0:
        if hist.close[-1] >= state['last_add_price'] + state['entry_atr']:
            new_position_size = state['position_size'] + RISK_PERCENTAGE * state['entry_price'] / (ATR_MULTIPLIER * state['entry_atr'])
            new_position_size = min(new_position_size, MAX_POSITION)
            if new_position_size > state['position_size']:
                state['last_add_price'] = hist.close[-1]
                state['position_size'] = new_position_size
                return {"target": new_position_size, "stop": state['entry_price'] - 2 * state['entry_atr'], "take": None}
    elif pos < 0:
        if hist.close[-1] <= state['last_add_price'] - state['entry_atr']:
            new_position_size = state['position_size'] - RISK_PERCENTAGE * state['entry_price'] / (ATR_MULTIPLIER * state['entry_atr'])
            new_position_size = max(new_position_size, -MAX_POSITION)
            if new_position_size < state['position_size']:
                state['last_add_price'] = hist.close[-1]
                state['position_size'] = new_position_size
                return {"target": new_position_size, "stop": state['entry_price'] + 2 * state['entry_atr'], "take": None}

    # Determine if we should exit due to opposite signal
    if pos > 0 and macd_line[-1] < signal_line[-1] and macd_line[-2] >= signal_line[-2]:
        state['in_cooldown'] = True
        state['cooldown_counter'] = 1
        return {"target": 0, "stop": None, "take": None}
    elif pos < 0 and macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]:
        state['in_cooldown'] = True
        state['cooldown_counter'] = 1
        return {"target": 0, "stop": None, "take": None}

    # Return current position with stop
    stop_price = state['entry_price'] - 2 * state['entry_atr'] if pos > 0 else state['entry_price'] + 2 * state['entry_atr']
    return {"target": pos, "stop": stop_price, "take": None}

