    if 'entry_price' not in state:
        state['entry_price'] = 0.0
    if 'entry_atr' not in state:
        state['entry_atr'] = 0.0
    if 'stop' not in state:
        state['stop'] = None
    if 'take' not in state:
        state['take'] = None
    if 'add_count' not in state:
        state['add_count'] = 0
    if 'last_add_price' not in state:
        state['last_add_price'] = 0.0
    if 'exit_bar' not in state:
        state['exit_bar'] = -COOLDOWN_BARS - 1  # Ensure we can enter on the first bar

    # Check for cooldown
    if t - state['exit_bar'] < COOLDOWN_BARS:
        return {"target": pos, "stop": None, "take": None}

    # Bull cross signal
    if macd_line[t] > signal_line[t] and macd_line[t-1] <= signal_line[t-1]:
        # Enter long position
        state['entry_price'] = hist.close[t]
        state['entry_atr'] = atr[t]
        state['stop'] = state['entry_price'] - ATR_MULTIPLIER * state['entry_atr']
        state['take'] = state['entry_price'] + ATR_MULTIPLIER * state['entry_atr']
        state['add_count'] = 0
        state['last_add_price'] = state['entry_price']
        state['exit_bar'] = -1  # Reset exit bar
        return {"target": ENTRY_RISK, "stop": state['stop'], "take": state['take']}

    # Bear cross signal
    if macd_line[t] < signal_line[t] and macd_line[t-1] >= signal_line[t-1]:
        # Exit position
        state['exit_bar'] = t
        return {"target": 0.0, "stop": None, "take": None}

    # Check for add
    if pos > 0 and state['add_count'] < ADD_LEVELS:
        if hist.close[t] >= state['last_add_price'] + ATR_MULTIPLIER * state['entry_atr']:
            state['add_count'] += 1
            state['last_add_price'] = hist.close[t]
            return {"target": pos + ADD_RISK, "stop": state['stop'], "take": state['take']}

    # Trail stop and take
    if pos > 0:
        new_stop = state['entry_price'] + (state['add_count'] * ATR_MULTIPLIER * state['entry_atr'])
        new_take = new_stop + (2 * ATR_MULTIPLIER * state['entry_atr'])
        if hist.close[t] >= new_stop:
            state['stop'] = new_stop
            state['take'] = new_take
        return {"target": pos, "stop": state['stop'], "take": state['take']}

    # No action
    return {"target": pos, "stop": None, "take": None}

