            state['long_high'] = hist.close[-1]
            state['pyramid_levels'] += 1
            return {"target": pos + state['position_size'], "stop": stop_price, "take": take_price}

        return {"target": pos, "stop": stop_price, "take": take_price}

    elif pos < 0:
        # Short position
        if ema_short[-1] > ema_long[-1]:
            return {"target": 0, "stop": None, "take": None}

        # Update trailing stop
        if 'short_low' not in state:
            state['short_low'] = hist.low[-1]
