            return {"target": 0, "stop": None, "take": None}
        if hist.low[t] <= take_price:
            return {"target": 0, "stop": None, "take": None}

    # Determine pyramid conditions
    if pos > 0 and state['additions'] < MAX_ADDITIONS:
        if hist.close[t] >= state['entry_price'] + state['entry_atr']:
            additional_size = state['position_size']
