    if pos == 0 and rsi[t] > RSI_OVERSOLD_LEVEL and rsi[t-1] <= RSI_OVERSOLD_LEVEL:
        state['entry_atr'] = atr[t]
        state['entry_price'] = hist.close[t]
        state['adds'] = 0
