    if pos > 0 and hist.close[t] <= lowest_low[t]:
        return {"target": 0, "stop": None, "take": None}
    if pos < 0 and hist.close[t] >= highest_high[t]:
        return {"target": 0, "stop": None, "take": None}

    # Determine if we should enter a long position
    if pos == 0 and not in_cooldown and hist.close[t] > highest_high[t - 1]:
        state['entry_bar'] = t
        state['last_add_bar'] = t
        state['adds'] = 0
        return {"target": position_size, "stop": lowest_low[t], "take": None}

    # Determine if we should enter a short position
    if pos == 0 and not in_cooldown and hist.close[t] < lowest_low[t - 1]:
        state['entry_bar'] = t
        state['last_add_bar'] = t
        state['adds'] = 0
        return {"target": -position_size, "stop": highest_high[t], "take": None}

    # Determine if we should add to a long position
    if pos > 0 and state['adds'] < MAX_ADDS and hist.close[t] >= hist.close[state['last_add_bar']] + ADDITIONAL_ATR * state['entry_atr']:
        state['last_add_bar'] = t
        state['adds'] += 1
        return {"target": pos + position_size, "stop": lowest_low[t], "take": None}

    # Determine if we should add to a short position
    if pos < 0 and state['adds'] < MAX_ADDS and hist.close[t] <= hist.close[state['last_add_bar']] - ADDITIONAL_ATR * state['entry_atr']:
        state['last_add_bar'] = t
        state['adds'] += 1
        return {"target": pos - position_size, "stop": highest_high[t], "take": None}

    # Continue with current position
    if pos > 0:
        return {"target": pos, "stop": lowest_low[t], "take": None}
    if pos < 0:
        return {"target": pos, "stop": highest_high[t], "take": None}

    # No position, no signal
    return {"target": 0, "stop": None, "take": None}

