    if pos == 0:
        if hist.close[-1] > box_high[-1] and box_high[-1] - box_low[-1] <= STOP_LOSS_ATR * entry_atr:
            # Go long
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = entry_atr
            state['bars_in_trade'] = 1
            state['take_profit'] = state['entry_price'] + TAKE_PROFIT_ATR * entry_atr
            state['stop_loss'] = state['entry_price'] - STOP_LOSS_ATR * entry_atr
            return {"target": position_size, "stop": state['stop_loss'], "take": state['take_profit']}
        elif hist.close[-1] < box_low[-1] and box_high[-1] - box_low[-1] <= STOP_LOSS_ATR * entry_atr:
            # Go short
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = entry_atr
            state['bars_in_trade'] = 1
            state['take_profit'] = state['entry_price'] - TAKE_PROFIT_ATR * entry_atr
            state['stop_loss'] = state['entry_price'] + STOP_LOSS_ATR * entry_atr
            return {"target": -position_size, "stop": state['stop_loss'], "take": state['take_profit']}

    # Manage existing position
    if pos != 0:
        state['bars_in_trade'] += 1

        # Bank half size if at least 2 ATR in profit
        if pos > 0 and hist.close[-1] >= state['entry_price'] + TAKE_PROFIT_ATR * entry_atr:
