            state['stop_price'] = state['entry_price'] - TRAILING_STOP_ATR * state['entry_atr']
            state['initial_pos'] = 1
            return {"target": 1.0, "stop": state['stop_price'], "take": state['take_price']}

        # Check for short entry condition
        if hist.high[t] >= state['armed_level'] and hist.close[t] < state['armed_level'] and hist.close[t] < ema_20[t]:
            state['entry_price'] = hist.close[t]
            state['entry_atr'] = atr[t]
