    # Determine if we have a valid signal
    if can_trade_today and pos == 0:
        if ema_short[t] > ema_long[t] and ema_short[t-1] <= ema_long[t-1]:  # Golden cross
            state['entry_price'] = hist.close[t]
            state['entry_atr'] = atr[t]
            state['signal_bar'] = t
            state['last_trade_day'] = current_day
            return {"target": 1.0, "stop": None, "take": None}
