    MAX_POSITION = 1.0
    MIN_POSITION = 0.05
    MAX_ENTRIES_PER_DAY = 3
    BOX_HEIGHT_ATR_LIMIT = 4
    BOX_SIZE = 32
    BREAKEVEN_ATR = 2
    SCALE_OUT_ATR = 1.5

    # Calculate ATR
    atr = ind.atr(hist, 14)
    entry_atr = atr[-1] if pos == 0 else state['entry_atr']

    # Calculate box
    box_high = ind.highest(hist.high, BOX_SIZE + 1)[-2]  # Exclude current bar
    box_low = ind.lowest(hist.low, BOX_SIZE + 1)[-2]    # Exclude current bar
    box_height = box_high - box_low

    # Volatility sizing
    position_size = RISK_PER_TRADE * hist.close[-1] / (ATR_MULT * entry_atr)
    position_size = min(MAX_POSITION, max(MIN_POSITION, position_size))

    # Check for new day
    current_day = hist.time[-1] // (1000 * 60 * 60 * 24)
    if 'current_day' not in state or state['current_day'] != current_day:
        state['current_day'] = current_day
        state['entries_today'] = 0

    # Entry conditions
    if pos == 0 and state['entries_today'] < MAX_ENTRIES_PER_DAY:
        if box_height <= BOX_HEIGHT_ATR_LIMIT * entry_atr:
            if hist.close[-1] > box_high:
                state['entry_atr'] = entry_atr
                state['entries_today'] += 1
                return {"target": position_size, "stop": box_low, "take": None}
            elif hist.close[-1] < box_low:
                state['entry_atr'] = entry_atr
                state['entries_today'] += 1
                return {"target": -position_size, "stop": box_high, "take": None}

    # Existing position logic
    if pos != 0:
        # Close on opposite signal
        if (pos > 0 and hist.close[-1] < box_low) or (pos < 0 and hist.close[-1] > box_high):
            return {"target": 0, "stop": None, "take": None}

        # Move stop to breakeven
        if pos > 0 and hist.close[-1] >= hist.close[-2] + BREAKEVEN_ATR * entry_atr:
            state['stop'] = hist.close[-2]
        elif pos < 0 and hist.close[-1] <= hist.close[-2] - BREAKEVEN_ATR * entry_atr:
            state['stop'] = hist.close[-2]

        # Scale out and bank half
        if pos > 0 and hist.close[-1] >= hist.close[-2] + SCALE_OUT_ATR * entry_atr:
            return {"target": pos / 2, "stop": state.get('stop', None), "take": None}
        elif pos < 0 and hist.close[-1] <= hist.close[-2] - SCALE_OUT_ATR * entry_atr:
            return {"target": pos / 2, "stop": state.get('stop', None), "take": None}

        # Return current stop
        return {"target": pos, "stop": state.get('stop', None), "take": None}

    # No position, no action
    return {"target": pos, "stop": None, "take": None}

