        # Check for stop loss
        if hist.low[t] <= state['stop_loss']:
            return {"target": 0.0, "stop": None, "take": None}

        # Determine additional entry conditions
        if hist.close[t] >= state['last_add_price'] + TAKE_PROFIT_ATR * state['entry_atr']:
            state['last_add_price'] = hist.close[t]
            state['take_profit'] = hist.close[t] + TAKE_PROFIT_ATR * state['entry_atr']
            return {"target": pos + ADDITIONAL_POSITION_SIZE, "stop": state['stop_loss'], "take": state['take_profit']}

    # No change in position
    return {"target": pos, "stop": state['stop_loss'] if pos > 0 else None, "take": state['take_profit'] if pos > 0 else None}
